<template>
  <main class="wa"><p v-if="context.readOnly" class="feedback">当前为制曲车间工作，您可查看记录和评分，仅所属车间管理员可修改。</p>
    <div v-if="context.isManager && tab==='assessment'" class="manager-detail-back"><button @click="tab=tab==='assessment'?'overview':'records'">← {{tab==='assessment'?'返回本周考评':'返回每周记录表'}}</button><b>{{managerDetailTitle}}</b></div>
    <div v-if="!['tasks','catalog','rules','members','documents'].includes(tab) && (context.isManager || tab==='work')" class="wa-filter card" :class="{'manager-filter':context.isManager || ['records','assessment'].includes(tab)}">
      <div v-if="context.isManager || ['records','assessment'].includes(tab)" class="natural-week"><div class="week-controls"><button class="week-arrow" aria-label="上一周" title="上一周" @click="moveWeek(-1)" :disabled="busy">‹</button><button class="week-picker" aria-label="选择自然周" aria-haspopup="dialog" :aria-expanded="weekCalendarOpen" :disabled="busy" @click="openWeekCalendar">{{weekCode(weekStart).replace('-W','年 第')}}周 ▾</button><button class="week-arrow" aria-label="下一周" title="下一周" @click="moveWeek(1)" :disabled="busy || weekStart>=monday(today())">›</button></div><span class="week-range">{{weekStart}} 至 {{weekEnd}} · 周一至周日</span></div><label v-else>填报日期<input type="date" v-model="weekInput" :max="today()" @change="loadWeek"></label>
      <label class="member-picker" v-if="context.isManager && ['assessment','records'].includes(tab)"><span class="visually-hidden">组长</span><select v-model="selectedUser" @change="loadWeek"><option value="">请选择人员</option><option v-for="m in context.members" :key="m.user_id" :value="String(m.user_id)">{{ m.floor }}楼 · {{ m.name }}</option></select></label>

      <label v-if="tab==='work' && own && editable" class="date-rest-setting">本周休息日<select :value="state.calendar?.restDate||''" :disabled="busy||loading" @change="setRest($event.target.value||null)"><option value="">请选择</option><option v-for="(day,i) in workDates" :key="day" :value="day">周{{['一','二','三','四','五','六'][i]}} · {{day}}</option></select></label>
      <button class="filter-refresh" @click="reload" :disabled="busy" aria-label="刷新" title="刷新">↻<span v-if="context.isManager"> 刷新</span></button>
    </div>
    <el-dialog v-model="weekCalendarOpen" title="选择自然周" width="min(360px, calc(100vw - 24px))" align-center append-to-body class="work-week-dialog"><el-calendar v-model="calendarMonth"><template #header><button aria-label="上个月" @click="moveCalendarMonth(-1)">‹</button><b>{{calendarMonth.getFullYear()}}年{{calendarMonth.getMonth()+1}}月</b><button aria-label="下个月" @click="moveCalendarMonth(1)">›</button></template><template #date-cell="{data}"><button class="calendar-day" :class="{'selected-week':monday(data.day)===weekStart}" :disabled="monday(data.day)>monday(today())" @click.stop="selectCalendarWeek(data.day);weekCalendarOpen=false">{{Number(data.day.slice(-2))}}</button></template></el-calendar><p class="calendar-help">点击任意日期，选择其所在的周一至周日。</p></el-dialog>
    <nav class="wa-tabs" :class="{'manager-tabs':context.isManager}" aria-label="工作管理功能">
      <button v-for="t in tabs" :key="t.key" :class="{ active: tab === t.key }" @click="changeTab(t.key)">{{ t.label }}<span v-if="t.key==='tasks' && taskBadgeCount>0" class="task-count-badge" :title="`${taskBadgeCount} 项${context.isManager?'待验收':'待完成或待补充'}任务`" :aria-label="`${taskBadgeCount} 项待处理任务`" aria-live="polite">{{taskBadgeCount>99?'99+':taskBadgeCount}}</span></button>
      <button v-if="context.isManager" class="settings-toggle" :class="{active:['members','rules','catalog','documents'].includes(tab)}" @click="changeTab('members')">班组设置</button>
    </nav>
    <nav v-if="context.isManager && ['members','rules','catalog','documents'].includes(tab)" class="manager-settings" aria-label="班组设置"><button v-for="item in managerSettingTabs" :key="item.key" :class="{active:tab===item.key}" @click="changeTab(item.key);managerSettingsOpen=false">{{item.label}}</button></nav>

    <p v-if="contextError" role="alert">{{contextError}} <button @click="reload().catch(()=>{})">重试</button></p><p v-else-if="contextLoading || loading" role="status">正在加载…</p>
    <div v-else-if="!selectedUser && !['rules','members','overview','statistics','tasks','catalog','documents'].includes(tab)" class="card empty">{{ context.isManager ? '请先在人员设置中添加组长，再选择人员。' : '请联系负责人，将您的账号加入考评人员。' }}</div>
    <WorkTasks v-else-if="tab==='tasks'" :manager="context.isManager" :read-only="context.readOnly" :members="context.members" :duties="context.duties||[]" :focus-id="taskFocusId" @clear-focus="taskFocusId=null" @change="taskChanged" />
    <WorkCatalog :read-only="context.readOnly || user.role!=='admin'" v-else-if="tab==='catalog' && context.isManager" @documents="openDocuments" />
    <WorkDocuments ref="documentsEditor" v-else-if="tab==='documents' && context.isManager" :read-only="user.role!=='admin'" :duty-id="documentDutyId" :week="documentCatalogWeek" @change="documentsChanged" />
    <template v-else-if="tab === 'work'">
      <p v-if="state.report?.feedback" class="feedback">{{state.report.status==='returned'?'待补充：':'复核意见：'}}{{state.report.feedback}}</p>
      <section class="day-status card" aria-live="polite"><div><b>{{pendingRefreshing?'正在更新待填事项…':offDay?'当日休息':`当日待填 ${dailyPending.length} 项`}}</b><small>{{selectedDutyDate()}} · 已提交 {{offDay?0:weekDuties.filter(d=>d.frequency==='每日'&&isDutySubmitted(d)).length}} / {{offDay?0:weekDuties.filter(d=>d.frequency==='每日').length}} 项</small><small>本周事项待填 {{weeklyPending.length}} 项 · 派发任务待办 {{taskPreviewError?'暂未获取':taskCount+' 项'}}</small><small v-if="pendingRefreshError" role="alert">待填数量更新失败，当前显示上次数据，请刷新。</small></div></section>
      <p v-if="offDay" class="feedback">{{isSunday?'周日不安排日常填报。':'今天已标记 R，免填当日事项。'}}每周事项仍需在工作日完成，派发任务按各自截止日期处理。</p>
      <section v-if="!offDay" class="duty-browser"><details v-for="group in fillCategories" :key="group.name" class="card category-group" open><summary><b>{{group.name}}</b><span>{{group.duties.filter(d=>d.frequency!=='持续'&&!isDutySubmitted(d)).length}} 项待填</span></summary><article v-for="duty in group.duties" :key="duty.id" class="category-task"><div class="category-task-copy"><h3>{{duty.title}}</h3><small>{{duty.frequency}} · {{duty.evidence}}{{duty.reportMode==='document'?(duty.documentScreenshotRequired?' · 在线填写后上传截图':duty.documentUrl?' · 在线文档':' · 照片或文档链接'):duty.reportMode==='photo'?' · 上传照片':''}}</small><a v-if="/^https?:\/\//i.test(duty.documentUrl||'')" class="bound-duty-document" :href="duty.documentUrl" target="_blank" rel="noopener noreferrer">在线文档：{{duty.documentTitle||'打开文档'}} ↗</a><span class="task-result">{{dutyResult(duty).label}}</span>
<section v-if="duty.id==='directive_tasks' && own" class="directive-tasks"><button v-if="editable" @click="openNew('duties','daily',duty)">补录临时指令 / 突发问题</button><header><b>班长当前派发任务</b><button @click="taskFocusId=null;tab='tasks'">全部任务 · {{taskCount}} 项待办</button></header><p v-if="taskPreviewError">任务加载失败 <button @click="loadTaskPreview">重试</button></p><p v-else-if="!taskRows.length">暂无班长派发任务，可记录临时指令或突发问题。</p><article v-for="task in taskRows.slice(0,3)" :key="task.id" class="directive-task"><div><b>{{task.title}}</b><span :class="{late:task.overdue}">{{taskStatusLabels[task.status]}}{{task.overdue?' · 已逾期':''}} · 截止 {{task.due_date}}</span></div><p>{{task.instructions}}</p><p v-if="task.feedback">班长意见：{{task.feedback}}</p><button @click="openAssignedTask(task)">{{['pending','returned'].includes(task.status)?'办理并上传验证材料':'查看任务材料'}}</button></article><small v-if="taskRows.length">任务提交后自动归入指令性工作；临时指令或突发问题可另行补录。</small></section></div><button v-if="own && editable" :class="{primary:currentDutyRecord(duty)?.status!=='submitted'}" @click="openDuty(duty)">{{currentDutyRecord(duty)?.status==='submitted'?'查看':duty.frequency==='持续'?'记录':'填报'}}</button><button v-else-if="currentDutyRecord(duty)" @click="openRecord(currentDutyRecord(duty),duty.id)">查看</button></article></details></section>
    </template>
    <template v-else-if="tab === 'records'">
      <WorkWeekSheet :selectable-week="!context.isManager" :refreshing="busy||loading" @select-week="openWeekCalendar" @refresh="reload" :week="weekStart" :name="selectedMemberName" :duties="state.duties||context.duties||[]" :records="state.records" :calendar="state.calendar" :can-export="context.isManager" :exporting="busy" @export-report="exportProductionReport" @open="openRecord" />
      <div v-if="context.isManager && selectedUser" class="section-tools"><button v-if="context.isManager && selectedUser" @click="exportWeek" :disabled="busy">导出本周表格</button></div>
      <details v-if="legacyRecords.length" class="legacy-records"><summary>历史专项记录（{{legacyRecords.length}} 条）</summary><div class="record-grid"><article v-for="r in legacyRecords" :key="r.id" class="card record"><div class="row"><h2>{{ recordLabel(r) }}</h2><span class="badge">已提交</span></div><p>{{ r.record_date }} · {{ r.payload.floor }}楼</p><p class="record-note">{{ recordSummary(r) }}</p><small>{{ r.photos.length }} 张照片</small><button @click="openRecord(r)">{{ own && editable ? '查看 / 编辑' : '查看详情' }}</button><button v-if="context.isManager && r.status==='submitted' && hasProductionAbnormal(r)" @click="exportProductionReport(r)" :disabled="busy">导出生产异常表</button></article></div>
      </details>
    </template>
    <template v-else-if="tab === 'assessment'">

      <section class="card monthly-score"><div class="row"><div class="monthly-title"><h2>月度考评</h2><span v-if="monthly" class="monthly-total" :aria-label="monthly.total==null?'当月成绩待全部周成绩发布':`当月得分 ${monthly.total} 分，满分 100 分`"><b>{{monthly.total==null?'待发布':monthly.total+' 分'}}</b><small>满分 100 分</small></span></div><input type="month" v-model="scoreMonth" aria-label="考评月份" @change="changeScoreMonth"></div><p v-if="monthError" role="status">{{monthError}}</p><template v-if="monthly"><div class="month-periods"><template v-for="p in monthly.periods" :key="p.index"><div v-if="context.isManager"><b>第{{p.index}}周</b><small>{{p.start.slice(5)}} 至 {{p.end.slice(5)}}</small><strong>{{p.score == null ? '待发布' : `得分 ${p.score} 分`}}</strong><small>满分 25 分</small></div><button v-else type="button" :aria-label="`查看第${p.index}周考评明细`" :aria-pressed="assessmentPeriodIndex===p.index" :class="{selected:assessmentPeriodIndex===p.index}" :disabled="busy" @click="selectAssessmentPeriod(p)"><b>第{{p.index}}周</b><small>{{p.start.slice(5)}} 至 {{p.end.slice(5)}}</small><strong>{{p.score == null ? '待发布' : `得分 ${p.score} 分`}}</strong><small>满分 25 分</small></button></template></div></template><details class="assessment-method"><summary>统计规则<span v-if="context.isManager && state.scoreJob?.status==='running'"> · 评分处理中</span><span v-else-if="context.isManager && state.scoreJob?.status==='failed'"> · 评分失败</span></summary><ol class="assessment-rule-list"><li v-if="monthly">{{monthly.method}}</li><li>各项依据工作结果、应填日期和验证材料复核。漏报、异常或未完成一次，即扣完该事项本周基础分，记为0分；其他事项不受影响。休息 R 及未到期限不计漏报，闭环加分另由班长确认。</li><li>每周日北京时间 08:00 生成本周建议，其他时间不自动评分。最终成绩由班长复核发布。</li><li v-if="context.isManager && state.scoreJob?.status==='running'" role="status">评分任务处理中；如长时间未完成，请联系系统管理员。</li><li v-else-if="context.isManager && state.scoreJob?.status==='failed'" role="status">本次评分失败：{{state.scoreJob.reason}}</li><li v-else-if="context.isManager && !aiSuggestion">尚未生成本周建议分，可由班长依据材料人工复核。</li><li v-if="context.isManager && aiSuggestion">生成时间：{{formatTime(aiSuggestion.generatedAt)}}<strong v-if="aiSuggestion.stale && state.report?.status!=='published'" class="photo-required"> · 材料或标准已变化，旧建议仅供参考，需重新核对。</strong></li><li v-if="aiNotice" role="status" class="ai-notice">{{aiNotice}}</li></ol></details><button v-if="user.role==='admin' && state.config?.length && state.report?.status!=='published'" class="primary" :disabled="busy" @click="suggestAssessment">{{busy?'正在生成…':'立即生成 AI 评分'}}</button></section><section v-if="!context.isManager && assessmentPeriod" class="assessment-period-detail"><h2>第{{assessmentPeriod.index}}周考评明细</h2><small>{{assessmentPeriod.start}} 至 {{assessmentPeriod.end}}</small><p v-if="periodLoading" role="status">正在加载考评详情…</p><p v-if="periodError" role="alert">{{periodError}}</p></section>
      <template v-if="!context.isManager && assessmentPeriod && !periodLoading && !periodError"><section v-for="source in periodDetails" :key="source.week" class="card period-source"><h3 v-if="periodDetails.length>1 || source.week<assessmentPeriod.start || addDays(source.week,6)>assessmentPeriod.end" class="period-source-title">评分来源：{{source.week}} 至 {{addDays(source.week,6)}}</h3><div class="period-score-summary"><span>AI 建议：{{suggestionTotal(source.data.suggestion)==null?'尚未生成':suggestionTotal(source.data.suggestion)+' 分'}}</span><b>{{source.data.report?.status==='published'?'班长已发布 · 得分 '+source.data.evaluation?.total+' 分':'待班长复核发布'}}</b></div><p v-if="source.data.suggestion?.stale && source.data.report?.status!=='published'">材料或标准已变化，原建议需重新核对。</p><p v-if="source.data.scoreJob?.status==='failed'" role="status">评分失败：{{source.data.scoreJob.reason}}</p><article v-for="rule in source.data.evaluation?.items||[]" :key="rule.id" class="period-score-item"><div class="row"><h2>{{rule.title}}</h2><div class="item-score"><b>{{rule.baseScore==null && rule.score==null?'待复核': '得分 '+(rule.baseScore??rule.score)+' 分'}}</b><small>满分 {{rule.max}} 分</small></div></div><p v-if="itemStandard(rule)"><b>本项要求：</b>{{itemStandard(rule)}}</p><WorkDeductionAudit :audit="deductionFor(rule,source.data)"/><p v-if="rule.bonus">经确认闭环 {{rule.closureCount}} 次，加 {{rule.bonus}} 分。</p><div v-if="periodSuggestion(source.data,rule)" class="suggestion-detail"><b>建议 {{periodSuggestion(source.data,rule).score}} 分</b><p>{{periodSuggestion(source.data,rule).reason}}</p></div><p v-if="source.data.report?.status==='published' && rule.reason"><b>最终评分理由：</b>{{rule.reason}}</p><details class="score-evidence"><summary>查看本项填报与照片（{{periodEvidence(source.data,rule).length}} 条）</summary><article v-for="record in periodEvidence(source.data,rule)" :key="record.id"><b>{{record.record_date}}</b><p>{{recordSummary(record)}}</p><div class="ledger-photos"><WorkPhoto v-for="photo in record.photos.filter(photo=>!rule.dutyId||photo.task_key===rule.dutyId)" :key="photo.id" :id="photo.id"/></div><button @click="openPeriodRecord(source.data,record,rule.dutyId||'')">查看完整记录</button></article><p v-if="!periodEvidence(source.data,rule).length">本期没有关联的已提交记录。</p></details></article></section></template>
      <template v-if="context.isManager"><div class="card score-head"><div><small>AI 建议总分{{state.report?.status==='published'?'（历史建议）':aiSuggestion?.stale?'（旧建议）':''}}</small><strong>{{suggestionTotal(aiSuggestion) ?? '—'}}<em> / {{scoreFullMark}}</em></strong></div><div><small>{{context.isManager?'班长确认分':'我的最终成绩'}} · {{ statusLabel }}</small><strong>{{ canReview && state.report?.status!=='published' ? (reviewTotal ?? '—') : (state.evaluation?.total ?? '—') }}<em> / {{scoreFullMark}}</em></strong></div><p>{{ state.report?.status === 'published' ? '已由负责人复核发布' : '' + (context.isManager?'右侧为班长确认分，核对各项依据后发布':'班长复核后，这里显示你的最终成绩') }}</p></div>
      <section v-for="r in state.evaluation?.items || []" :key="r.id" class="card score-item"><div class="row"><h2>{{ r.title }}</h2><div class="item-score"><b>{{ itemScore(r) == null ? '待复核' : `得分 ${itemScore(r)} 分` }}</b><small>满分 {{ r.max }} 分</small></div></div><p v-if="itemStandard(r)"><b>本项要求：</b>{{ itemStandard(r) }}</p><WorkDeductionAudit :audit="deductionFor(r)"/><p v-if="r.bonus">经确认闭环 {{r.closureCount}} 次，加 {{r.bonus}} 分；计入周总分封顶。</p><div class="suggestion-detail" v-if="suggestionFor(r.id)"><b>{{suggestionFor(r.id).source==='formula'?'按规则计算':'AI 建议'}} {{suggestionFor(r.id).score}} / {{r.max}} 分</b><p>{{suggestionFor(r.id).reason}}</p></div><p v-if="state.report?.status==='published'"><b>最终评分理由：</b>{{r.reason}}</p><details class="score-evidence"><summary>查看本项填报与照片（{{evidenceFor(r).length}} 条）</summary><article v-for="record in evidenceFor(r)" :key="record.id"><b>{{record.record_date}}</b><p>{{recordSummary(record)}}</p><div class="ledger-photos"><WorkPhoto v-for="photo in record.photos.filter(p=>!r.dutyId||p.task_key===r.dutyId)" :key="photo.id" :id="photo.id"/></div><button @click="openRecord(record,r.dutyId||'')">查看完整记录</button></article><p v-if="!evidenceFor(r).length">没有关联的已提交记录。</p></details><small v-if="r.evidence?.length">依据记录：{{ r.evidence.join('、') }}</small>
        <div v-if="canReview && state.report?.status !== 'published'" class="manual-fields"><label>班长确认分<input type="number" min="0" :max="baseScoreLimit(r)" step="0.1" v-model="manual[r.id].score"></label><div v-if="r.bonusPerClosure"><b>确认闭环（每条加0.5分，周总分封顶25分）</b><label v-for="record in closureRecords(r)" :key="record.id" class="check-line"><input type="checkbox" :value="record.id" v-model="manual[r.id].closureRecordIds">{{record.record_date}} · {{record.payload.checks.find(c=>c.dutyId===r.dutyId)?.action}}</label><small v-if="!closureRecords(r).length">暂无填写闭环处理情况的记录</small></div><label>确认或改分理由<textarea v-model="manual[r.id].reason" placeholder="依据记录和现场核对情况说明最终得分" maxlength="2000"></textarea></label></div>
      </section>
      <details v-if="context.isManager" class="card review-ledger"><summary>全部履职明细与照片</summary><div class="section-heading"><div><h2>履职明细</h2><p>{{selectedMemberName}} · 按事项查看本周填报结果和验证材料</p></div><span>{{state.records.filter(r=>r.kind==='duties'&&r.status==='submitted').length}} 条填报</span></div>
        <div class="ledger-table-wrap"><table class="ledger-table"><thead><tr><th>人员</th><th>日期</th><th>工作事项</th><th>工作内容</th><th>频次</th><th>输出依据</th><th>选择结果</th><th>验证情况</th><th>验证材料</th></tr></thead><tbody><tr v-for="row in dutyReviewRows" :key="row.key"><td data-label="人员">{{row.name}}</td><td data-label="日期">{{row.date}}</td><td data-label="工作事项">{{row.category}}</td><td data-label="工作内容">{{row.title}}</td><td data-label="频次"><span class="badge">{{row.frequency}}</span></td><td data-label="输出依据">{{row.evidence}}</td><td data-label="选择结果"><b>{{row.status||'未选择'}}</b></td><td data-label="验证情况" class="ledger-note">{{[row.note,row.action,row.reference].filter(Boolean).join('；')||'—'}}</td><td data-label="验证材料"><div v-if="row.photos.length" class="ledger-photos"><WorkPhoto v-for="photo in row.photos" :key="photo.id" :id="photo.id"/></div><span v-else>—</span></td></tr><tr v-if="!dutyReviewRows.length"><td colspan="9" class="ledger-empty">本周暂无日常履职填报</td></tr></tbody></table></div>
      </details>
      <section class="card" v-if="canReview && state.config?.length"><h2>负责人复核</h2><textarea v-model="feedback" rows="3" maxlength="5000" placeholder="复核意见；退回时请说明需补充或修改的内容"></textarea><div class="review-actions"><button :disabled="busy" @click="review('return')">退回补充</button><button v-if="state.report?.status !== 'published'" class="primary" :disabled="busy" @click="review('publish')">确认并发布成绩</button></div></section>
      <section class="card" v-if="state.events?.length"><h2>处理记录</h2><p v-for="(e,i) in state.events" :key="i">{{ e.created_at }} · {{ e.actor || '系统定时任务' }} · {{ eventNames[e.action] || e.action }} <span v-if="e.detail?.feedback">— {{ e.detail.feedback }}</span></p></section>
      </template>
    </template>
    <template v-else-if="tab === 'rules'">
      <section class="card">
        <div class="rule-toolbar"><label>车间<select v-model="ruleWorkshop" @change="loadRules"><option v-for="(v,k) in allowedWorkshops" :key="k" :value="k">{{v}}</option></select></label><span class="shared-rule-scope">全体制曲组长共用标准 · 管理员统一维护</span></div>
        <p>按工作分类维护分值和评分标准，合计 25 分；填 0 不计分。管理员统一维护，保存后立即执行，未修改持续沿用；已发布成绩保留原标准。</p>
        <p class="rule-load-notice" role="status">{{rulesLoading?'正在加载事项与标准…':rulesNotice}}</p>
        <fieldset :disabled="ruleReadOnly || rulesLoading" class="scope-fields">
