:00"></label><label>结束时间<input v-model="checkFor(activeDuty.id).productionReport.endTime" :disabled="!canEditRecord" placeholder="如 16:30"></label></div><div class="form-pair"><label>AGV数量<input v-model="checkFor(activeDuty.id).productionReport.agvCount" :disabled="!canEditRecord" inputmode="numeric"></label><label>下线车号<input v-model="checkFor(activeDuty.id).productionReport.vehicleNo" :disabled="!canEditRecord"></label></div><label>维修进度<textarea v-model="checkFor(activeDuty.id).productionReport.repairProgress" rows="2" :disabled="!canEditRecord"></textarea></label><div v-for="(issue,i) in checkFor(activeDuty.id).productionReport.issues" :key="i" class="production-issue"><div class="form-pair"><label>影响因素<select v-model="issue.factorType" @change="issue.category=issue.factorType==='其他'?'':issue.factorType" :disabled="!canEditRecord"><option value="">请选择</option><option>设备</option><option>人员</option><option>其他</option></select></label><label>耽误总时长<input v-model="issue.delay" :disabled="!canEditRecord" placeholder="如 60分钟"></label></div><label v-if="issue.factorType==='其他'">影响因素名称<input v-model="issue.category" maxlength="30" :disabled="!canEditRecord" placeholder="如：曲块、原料、环境"></label><label>具体原因<textarea v-model="issue.description" rows="2" :disabled="!canEditRecord"></textarea></label><button v-if="canEditRecord && checkFor(activeDuty.id).productionReport.issues.length>1" @click="checkFor(activeDuty.id).productionReport.issues.splice(i,1)">删除问题</button></div><button v-if="canEditRecord" @click="addProductionIssue(checkFor(activeDuty.id))">添加问题分析</button><label>改进措施<textarea v-model="checkFor(activeDuty.id).productionReport.measuresText" rows="3" :disabled="!canEditRecord" placeholder="每项措施单独一行"></textarea></label></section><label v-if="activeDuty.abnormalOptions.includes(checkFor(activeDuty.id).status) && !isProduction(activeDuty)">处理 / 闭环情况<textarea v-model="checkFor(activeDuty.id).action" rows="2" maxlength="2000" :disabled="!canEditRecord" placeholder="未完成事项说明计划；