const cadences = [
  {key:'daily',title:'每日事项',description:'选择本项结果，填写对应验证情况。'},
  {key:'weekly',title:'每周事项',description:'本周完成一次；可上传照片并填写对应记录。'},
  {key:'continuous',title:'持续事项',description:'有情况或需要留痕时随时记录，可多次提交。'},
]
const cadenceByKey = Object.fromEntries(cadences.map(c=>[c.key,c]))
const workshops = {raw_grain:'原粮车间',qu_making:'制曲车间',brewing:'酿酒车间'}
const eventNames = {submitted:'提交周考评',published:'发布成绩',returned:'退回补充',record_created:'新增填报',record_updated:'修改填报',photo_added:'上传照片',photo_removed:'移除照片',ai_suggested:'生成智能评分建议',rest_changed:'调整休息日'}
