function openNew(kind,mode=null,duty=null){clearPending();const base={kind,date:selectedDutyDate(),floor:state.value.member.floor,note:'',theme:'',location:'',noIssue:false,action:'',thickness:Array(10).fill(''),lines:Array.from({length:4},()=>({gap:'',crushing:''})),photos:[],...(kind!=='duties'?{format:'simple',result:'',reference:''}:{})};if(kind==='duties'){base.mode=mode;base.checks=duty?[{dutyId:duty.id,taskAssignmentIds:[],status:'',note:'',action:'',reference:duty.documentUrl||'',...(isProduction(duty)?{productionReport:blankProductionReport()}:{})}]:[]}form.value=base;activeDutyId.value=duty?.id||'';if(duty)activeCategory.value=duty.category;baseline.value=JSON.stringify(form.value);editor.value=true}
