async function closeEditor(){if(busy.value)return;if(dirty()){try{await ElMessageBox.confirm('有尚未保存的内容，确定放弃吗？','关闭填报',{confirmButtonText:'放弃',cancelButtonText:'继续填写'})}catch{return}}editor.value=false}
async function saveRecord(){const status='submitted';if(form.value.format==='simple'&&form.value.result==='正常'){form.value.note='';form.value.reference='';form.value.action=''}normalizeDutyChecks();await run(async()=>{const queued=[...pendingPhotoFiles.value],initialStatus=queued.length?'draft':status;const r=await work.post('/records',{...form.value,status:initialStatus});Object.assign(form.value,r.data);if(queued.length){for(const photo of queued)await uploadPhotoBlob(photo.blob,photo.itemKey);clearPending();await loadWeek();form.value.photos=state.value.records.find(x=>String(x.id)===String(form.value.id))?.photos||[];if(status==='submitted'&&missingDutyPhotos.value.length){baseline.value=JSON.stringify(form.value);ElMessage.warning(`照片已上传，但仍缺少：${missingDutyPhotos.value.map(x=>x.title).join('、')}`);return}if(status==='submitted'){const submitted=await work.post('/records',{...form.value,status:'submitted'});Object.assign(form.value,submitted.data)}}baseline.value=JSON.stringify(form.value);ElMessage.success('记录已提交');await loadWeek();if(status==='submitted')editor.value=false})}
async function shrink(file){if(!['image/jpeg','image/png'].includes(file.type))throw new Error('请选择 JPG 或 PNG 照片');if(file.size>25*1024*1024)throw new Error('照片过大，请选择 25MB 以内的图片');const img=await createImageBitmap(file);try{const scale=Math.min(1,1600/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);return await new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(new Error('图片处理失败')),'image/jpeg',.85))}finally{img.close()}}
async function uploadPhotoBlob(blob,itemKey=null){const data=new FormData();data.append('photo',blob,'photo.jpg');if(itemKey)data.append('itemKey',itemKey);await work.post(`/records/${form.value.id}/photos`,data)}
async function uploadPhoto(e,itemKey=null){const file=e.target.files?.[0];e.target.value='';if(!file)return;let blob;try{blob=await shrink(file)}catch(err){ElMessage.error(err.message);return}const count=photosFor(itemKey).length+pendingFor(itemKey).length;if(count>=6){ElMessage.warning('每项最多添加 6 张照片');return}if(!form.value.id){pendingPhotoFiles.value=[...pendingPhotoFiles.value,{key:`${Date.now()}-${Math.random()}`,itemKey,blob,url:URL.createObjectURL(blob)}];return}await run(async()=>{await uploadPhotoBlob(blob,itemKey);await loadWeek();form.value.photos=state.value.records.find(r=>String(r.id)===String(form.value.id))?.photos||[];baseline.value=JSON.stringify({...JSON.parse(baseline.value),photos:form.value.photos});ElMessage.success('照片已上传')})}
async function removePhoto(id){await run(async()=>{await work.delete(`/photos/${id}`);form.value.photos=form.value.photos.filter(p=>p.id!==id);baseline.value=JSON.stringify({...JSON.parse(baseline.value),photos:form.value.photos});await loadWeek()})}
async function suggestAssessment(){await run(async()=>{await ElMessageBox.confirm(`为 ${selectedMemberName.value} 生成 ${weekStart.value} 至 ${weekEnd.value} 的 AI 建议分？历史建议保留。`,'手动评分');const result=await work.post('/suggest',{userId:selectedUser.value,week:weekStart.value});if(!result.data.available){aiNotice.value=result.data.reason;aiSuggestion.value=null;return}aiSuggestion.value=result.data;for(const item of result.data.suggestions)manual.value[item.ruleId]={score:item.score,reason:item.reason,closureRecordIds:[]};aiNotice.value='建议分和理由已填入下方，班长可逐项修改后确认发布。';ElMessage.success('评分建议已生成')})}
async function review(action){await run(async()=>{
  if(action==='publish'){
    const excess=(state.value.config||[]).find(rule=>Number(manual.value[rule.id]?.score)>baseScoreLimit(rule));
    if(excess){ElMessage.warning(`“${excess.title}”基础分最多 ${baseScoreLimit(excess)} 分，请按扣分依据调整后发布`);return}
  }
  await ElMessageBox.confirm(action==='publish'?'确认工作记录、照片和最终分数无误后发布？':'退回后组长可补充修改本周记录。','复核确认');
  await work.post('/review',{userId:selectedUser.value,week:weekStart.value,revision:state.value.report?.revision||0,rulesKey:state.value.rulesKey,action,feedback:feedback.value,manual:manual.value,suggestionId:aiSuggestion.value?.stale?null:aiSuggestion.value?.suggestionId||null});
  await loadWeek();ElMessage.success('复核已保存')
})}
async function taskChanged(){await loadTaskPreview();await loadWeek({quiet:true})}
async function loadRules(){
  if(!context.value.isManager)return
  const seq=++rulesLoadSequence
  rulesLoading.value=true;rulesNotice.value=''
  try{
    const start=monday(today())
    if(!start){ruleDraft.value=[];rulesNotice.value='请选择有效的生效日期';return}
    const r=await work.get('/rules',{params:{workshop:ruleWorkshop.value}})
    if(seq!==rulesLoadSequence)return
    effectiveWeek.value=r.data.effectiveWeek||start
    ruleDuties.value=(r.data.duties||r.data.entries||[]).filter(d=>d.active!==false)
    ruleDraft.value=catalogRuleDraft(ruleDuties.value,r.data.current?.rules||r.data.draft?.rules||[],r.data.defaultRules||[])
    ruleHistory.value=r.data.history||[]

    rulesNotice.value=r.data.current
      ? '已加载当前统一标准。'
      : r.data.draft ? '已载入最近保存的班组标准供整理；管理员保存后全班组统一执行。' : ruleReadOnly.value ? '管理员尚未保存统一标准。' : `已生成 ${ruleDraft.value.length} 项完整清单，请填写分值。评判标准可修改。`
    if(rulesBeforeDocuments.value?.workshop===ruleWorkshop.value){ruleDraft.value=rulesBeforeDocuments.value.items;rulesBeforeDocuments.value=null;rulesNotice.value='已保留进入在线文档前的评分标准修改，请保存标准。'}
  }catch{if(seq===rulesLoadSequence){ruleDraft.value=[];ruleHistory.value=[];rulesNotice.value='该周事项与标准加载失败，请检查网络后重新进入事项分值。'}}
  finally{if(seq===rulesLoadSequence)rulesLoading.value=false}
}
function addCustomRule(){ruleDraft.value.unshift({custom:true,customId:`custom_${Date.now()}_${Math.random().toString(36).slice(2,10)}`,category:'其他事项',title:'',kind:'manual',max:'',standard:'',bonusPerClosure:0})}
function addExistingRule(event){const duty=ruleDuties.value.find(d=>d.id===event.target.value);if(duty&&!ruleDraft.value.some(r=>r.dutyId===duty.id))ruleDraft.value.push(catalogRuleDraft([duty])[0]);event.target.value=''}
function ruleDuty(rule){return (ruleDuties.value.length?ruleDuties.value:context.value.duties||[]).find(duty=>duty.id===rule.dutyId)||null}
function selectRuleDuty(rule){const duty=ruleDuty(rule);rule.title=duty?.title||'';rule.kind='manual'}
function deductionFor(rule,data=state.value){return rule.deductionAudit||data.deductionAudits?.find(item=>String(item.ruleId)===String(rule.id))?.audit||null}
function baseScoreLimit(rule){const audit=deductionFor(rule);return audit?.calendarConfirmed?audit.scoreLimit:rule.max}
function itemScore(rule){const value=canReview.value && state.value.report?.status!=='published'?manual.value[rule.id]?.score:(rule.baseScore ?? rule.score);return value==null||value===''?null:state.value.report?.status==='published'?value:Math.min(Number(value),baseScoreLimit(rule))}
function itemStandard(rule){return String(rule.standard||'').replace(/^依据本项工作结果、应填日期和验证材料复核；休息R不扣分。/,'').trim()}
async function saveRules(){if(!canSaveRules.value){ElMessage.warning(ruleProblems.value[0]);return}await run(async()=>{const result=await work.post('/rules',{workshop:ruleWorkshop.value,rules:ruleDraft.value.filter(r=>Number(r.max)>0)});ElMessage.success(result.data.unchanged?'评分标准未变化，继续沿用':'评分标准已保存，立即执行');await loadRules();await loadWeek();await loadOverview()})}
async function saveMember(){await run(async()=>{await work.post('/members',memberForm.value);await reload();ElMessage.success('楼层组长分配已保存')})}
async function exportWeek(){await run(async()=>{const b=await work.get('/export',{params:{userId:selectedUser.value,week:weekStart.value},responseType:'blob'});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`履职记录_${weekStart.value}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)})}
async function exportProductionReport(record){await run(async()=>{const b=await work.get(`/records/${record.id}/production-report`,{responseType:'blob'});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`生产异常跟踪表_${record.record_date}.docx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)})}
async function loadOverview(){if(!context.value.isManager||!weekStart.value)return;overviewWorkshop.value=context.value.scope||overviewWorkshop.value;const r=await work.get('/overview',{params:{workshop:overviewWorkshop.value,week:weekStart.value}});overview.value=r.data}
watch([tab,weekStart],()=>{if(tab.value==='work'){loadTaskPreview();loadWeek({quiet:true}).catch(()=>{})}if(tab.value==='rules')loadRules();if(tab.value==='overview')loadOverview().catch(()=>{});else if(['assessment','records'].includes(tab.value))loadWeek().catch(()=>{})})
function refreshPending(){if(document.visibilityState==='visible'&&tab.value==='work'&&!contextLoading.value&&!busy.value&&!editor.value&&!pendingRefreshing.value){loadWeek({quiet:true}).catch(()=>{});loadTaskPreview()}}
function leave(e){if(dirty()){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(()=>!dirty()||confirmDiscard('有未保存的修改，确定离开吗？'))
onMounted(()=>{reload().catch(()=>{});window.addEventListener('beforeunload',leave);window.addEventListener('focus',refreshPending);document.addEventListener('visibilitychange',refreshPending)})
onBeforeUnmount(()=>{clearPending();window.removeEventListener('beforeunload',leave);window.removeEventListener('focus',refreshPending);document.removeEventListener('visibilitychange',refreshPending);loadSequence++})
</script>

